import java.net.URLClassLoader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;

public class TallyGate {
    public static int tint_span(Path exploded, Path roster, Path jar) throws Exception {
        if (!Files.isRegularFile(jar)) {
            return 1;
        }
        Set<String> required = new HashSet<String>();
        for (String line : Files.readAllLines(roster)) {
            String s = line.trim();
            if (!s.isEmpty()) {
                required.add(s.split("\\s+", 2)[0]);
            }
        }

        // Use an isolated loader: checking blastcp would hide omissions from
        // the artifact that taste and booth actually use.
        try (URLClassLoader loader = new URLClassLoader(
                new java.net.URL[] { jar.toUri().toURL() },
                ClassLoader.getPlatformClassLoader());
             JarFile jf = new JarFile(jar.toFile())) {
            java.util.Enumeration<JarEntry> entries = jf.entries();
            while (entries.hasMoreElements()) {
                String n = entries.nextElement().getName();
                if (n.endsWith("Booth.class") && !n.contains("/")) {
                    Class.forName(n.substring(0, n.length() - 6), true, loader);
                }
            }
            Class<?> rib = Class.forName("Rib", true, loader);
            java.lang.reflect.Method all = rib.getDeclaredMethod("all");
            all.setAccessible(true);
            @SuppressWarnings("unchecked")
            List<String> live = (List<String>) all.invoke(null);
            return live.containsAll(required) ? 0 : 1;
        }
    }

    public static void main(String[] args) throws Exception {
        System.exit(tint_span(
            Paths.get("/app/blastcp"),
            Paths.get("/app/desknote/NAMES.txt"),
            Paths.get("/app/jarwell/husk.jar")));
    }
}
